<?php
declare(strict_types=1);
require_once __DIR__.'/includes/config.php';
$ok=true;$msg='';$tablas=[];$usuarios=[];$sa=0;
try{$pdo=conectarBD();$tablas=$pdo->query('SHOW TABLES')->fetchAll(PDO::FETCH_COLUMN);if(in_array('usuarios',$tablas,true)){ $usuarios=$pdo->query('SELECT id,pc_identificador,nombre_usuario,rol,activo,estado_pc,fecha_creacion,fecha_ultima_conexion FROM usuarios ORDER BY id')->fetchAll();$sa=(int)$pdo->query("SELECT COUNT(*) FROM usuarios WHERE rol='superadmin'")->fetchColumn();}$msg='Conexión correcta.';}catch(Throwable $e){$ok=false;$msg='Error: '.$e->getMessage();}
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ESG — Diagnóstico</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><div class="container py-4"><h1>ESG — Diagnóstico</h1><div class="alert alert-<?=$ok?'success':'danger'?>"><?=e($msg)?></div><h2 class="h5">Tablas</h2><ul><?php foreach($tablas as $t):?><li><?=e((string)$t)?></li><?php endforeach;?></ul><h2 class="h5">SuperAdmin</h2><p><?=$sa?'Existe un SuperAdmin.':'NO existe un SuperAdmin.'?></p><h2 class="h5">Usuarios</h2><div class="table-responsive"><table class="table table-bordered table-sm bg-white"><tr><th>ID</th><th>IP</th><th>Usuario</th><th>Rol</th><th>Activo</th><th>PC</th><th>Última conexión</th></tr><?php foreach($usuarios as $u):?><tr><td><?=$u['id']?></td><td><?=e($u['pc_identificador'])?></td><td><?=e($u['nombre_usuario'])?></td><td><?=e($u['rol'])?></td><td><?=$u['activo']?'Sí':'No'?></td><td><?=e($u['estado_pc'])?></td><td><?=e($u['fecha_ultima_conexion'])?></td></tr><?php endforeach;?></table></div></div></body></html>
